// Offline support: serve files from the cache, refresh them in the background.
// VERSION and ASSETS are generated by scripts/stamp-sw.mjs (runs on `npm start` and on every deploy):
// VERSION is a fingerprint of the app files, so any change makes phones fetch the new version.
const VERSION = 'chord-coach-a4f4046edd';
const ASSETS = [
  './',
  'icons/icon-180.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon.svg',
  'index.html',
  'js/app.js',
  'js/audio.js',
  'js/dom.js',
  'js/keyboard.js',
  'js/store.js',
  'js/theory.js',
  'js/ultimate-guitar.js',
  'js/views/chords.js',
  'js/views/quiz.js',
  'js/views/songs.js',
  'manifest.webmanifest',
  'styles.css',
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin) return;
  e.respondWith(
    caches.open(VERSION).then(async cache => {
      const cached = await cache.match(e.request, { ignoreSearch: true });
      const fresh = fetch(e.request)
        .then(res => {
          if (res.ok) cache.put(e.request, res.clone());
          return res;
        })
        .catch(() => cached);
      return cached || fresh;
    }),
  );
});
